import { randomUUID } from 'node:crypto';

const MAX_PROMOS_PER_DAY = 3;
const MIN_GAP_MS = 2 * 60 * 60 * 1000;
const KEEP_MS = 72 * 60 * 60 * 1000;

const formatters = new Map();

// Returns a formatter for the zone, or null if the zone name is invalid.
function formatterFor(timeZone) {
  if (typeof timeZone !== 'string' || timeZone === '') return null;
  if (formatters.has(timeZone)) return formatters.get(timeZone);
  let f = null;
  try {
    f = new Intl.DateTimeFormat('en-US', {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    });
  } catch {
    f = null;
  }
  formatters.set(timeZone, f);
  return f;
}

// Calendar day (midnight to midnight) of the instant in the given zone.
function dayKey(formatter, ms) {
  const p = formatter.formatToParts(new Date(ms));
  let y = '', m = '', d = '';
  for (const part of p) {
    if (part.type === 'year') y = part.value;
    else if (part.type === 'month') m = part.value;
    else if (part.type === 'day') d = part.value;
  }
  return `${y}-${m}-${d}`;
}

export function createGate() {
  // userId -> Map(id -> sendTimeMs), promos only
  const promos = new Map();
  // id -> userId, for cancel
  const owners = new Map();

  const deny = (rule) => ({ allowed: false, rule, id: null });

  function request({ userId, timeZone, category, now } = {}) {
    if (category !== 'promo' && category !== 'security') return deny('invalid-category');
    if (!(now instanceof Date) || Number.isNaN(now.getTime())) return deny('invalid-time');
    const nowMs = now.getTime();

    if (category === 'security') {
      // Security alerts are never limited by promo policy and do not count toward it.
      return { allowed: true, rule: '', id: randomUUID() };
    }

    if (typeof userId !== 'string' || userId === '') return deny('invalid-user');
    const fmt = formatterFor(timeZone);
    if (!fmt) return deny('invalid-time-zone');

    let sends = promos.get(userId);
    if (!sends) {
      sends = new Map();
      promos.set(userId, sends);
    }

    // Drop old records so memory stays bounded.
    for (const [id, t] of sends) {
      if (t < nowMs - KEEP_MS) {
        sends.delete(id);
        owners.delete(id);
      }
    }

    let sameDay = 0;
    let tooClose = false;
    const today = dayKey(fmt, nowMs);
    for (const t of sends.values()) {
      if (Math.abs(nowMs - t) < MIN_GAP_MS) tooClose = true;
      if (dayKey(fmt, t) === today) sameDay++;
    }

    if (tooClose) return deny('min-gap');
    if (sameDay >= MAX_PROMOS_PER_DAY) return deny('daily-cap');

    const id = randomUUID();
    sends.set(id, nowMs);
    owners.set(id, userId);
    return { allowed: true, rule: '', id };
  }

  function cancel(id) {
    const userId = owners.get(id);
    if (userId === undefined) return;
    owners.delete(id);
    const sends = promos.get(userId);
    if (sends) {
      sends.delete(id);
      if (sends.size === 0) promos.delete(userId);
    }
  }

  return { request, cancel };
}

import assert from 'node:assert/strict';
import { createGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/knock-d2-3/bot.mjs';

const LA = 'America/Los_Angeles';
const q = (g, t, o = {}) => g.request({ userId: 'u', timeZone: LA, category: 'promo', now: new Date(t), ...o });

// LA is UTC-7 in July: local midnight = 07:00Z
let g = createGate();
assert.ok(q(g, '2026-07-10T07:00:00Z').allowed);
assert.equal(q(g, '2026-07-10T08:59:59Z').rule, 'min-gap');
assert.ok(q(g, '2026-07-10T09:00:00Z').allowed);
assert.ok(q(g, '2026-07-10T11:00:00Z').allowed);
const r = q(g, '2026-07-10T13:00:00Z');
assert.deepEqual(r, { allowed: false, rule: 'daily-cap', id: null });
// next local day starts 07:00Z on the 11th
assert.ok(q(g, '2026-07-11T06:59:00Z').allowed === false);
assert.ok(q(g, '2026-07-11T07:00:00Z').allowed);

// Same instants, different zone: Berlin (UTC+2) midnight = 22:00Z
g = createGate();
const B = { timeZone: 'Europe/Berlin' };
assert.ok(q(g, '2026-07-10T21:00:00Z', B).allowed); // Jul 10 local 23:00
assert.ok(q(g, '2026-07-10T22:00:00Z', B).rule === 'min-gap');
assert.ok(q(g, '2026-07-11T00:00:00Z', B).allowed); // Jul 11 local 02:00, new day

// cancel frees slot and gap
g = createGate();
const a = q(g, '2026-07-10T10:00:00Z');
assert.equal(q(g, '2026-07-10T10:30:00Z').rule, 'min-gap');
g.cancel(a.id);
g.cancel(a.id); g.cancel('nope');
assert.ok(q(g, '2026-07-10T10:30:00Z').allowed);

// cancel restores daily cap
g = createGate();
const ids = [10, 12, 14].map((h) => q(g, `2026-07-10T${h}:00:00Z`).id);
assert.equal(q(g, '2026-07-10T16:00:00Z').rule, 'daily-cap');
g.cancel(ids[1]);
assert.ok(q(g, '2026-07-10T16:00:00Z').allowed);

// security unlimited, doesn't count, users independent
g = createGate();
for (let i = 0; i < 10; i++) assert.ok(q(g, '2026-07-10T10:00:00Z', { category: 'security' }).allowed);
assert.ok(q(g, '2026-07-10T10:00:00Z').allowed);
assert.ok(q(g, '2026-07-10T10:00:00Z', { userId: 'v' }).allowed);

// DST: LA fall back 2026-11-01 (25h day) ; all 3 fit, 4th blocked
g = createGate();
for (const t of ['07:00', '10:00', '13:00']) assert.ok(q(g, `2026-11-01T${t}:00Z`).allowed); // 00:00,03:00(PDT)...
assert.equal(q(g, '2026-11-01T16:00:00Z').rule, 'daily-cap'); // 08:00 PST same day

// bad input
assert.equal(q(g, '2026-07-10T10:00:00Z', { timeZone: 'Nope/Zone' }).rule, 'invalid-time-zone');
assert.equal(q(g, '2026-07-10T10:00:00Z', { category: 'x' }).rule, 'invalid-category');
console.log('all ok');
